@CrossOrigin
@RestController
@RequestMapping("/ThirdPartyQuery")
public class ThirdPartyQueryRestController extends BaseSpringRestController {
	
	public ThirdPartyQueryRestController( ThirdPartyService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a ThirdParty using a UUID
     * @param		UUID thirdPartyId
     * @return		ThirdParty
     */    
    @GetMapping("/load")
    public ThirdParty load( @RequestParam(required=true) UUID thirdPartyId ) {
    	ThirdParty entity = null;

    	try {  
    		entity = service.getThirdParty( new ThirdPartyFetchOneSummary( thirdPartyId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load ThirdParty using Id " + thirdPartyId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all ThirdParty business objects
     * @return		Set<ThirdParty>
     */
    @GetMapping("/")
    public List<ThirdParty> loadAll() {                
    	List<ThirdParty> thirdPartyList = null;
        
    	try {
            // load the ThirdParty
            thirdPartyList = service.getAllThirdParty();
            
            if ( thirdPartyList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all ThirdPartys" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all ThirdPartys ", exc );
        	return null;
        }

        return thirdPartyList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected ThirdParty thirdParty = null;
    protected ThirdPartyService service = null;
    private static final Logger LOGGER = Logger.getLogger(ThirdPartyQueryRestController.class.getName());
    
}
